    if (y instanceof FBigNum) {
        BigInteger b = y.getBigInteger();
        if (b.bitLength() < 64) return b.longValue();
        return (b.signum() < 0) ? java.lang.Long.MIN_VALUE : java.lang.Long.MAX_VALUE;
    }
    return y.getLong();
}

